    data class Frame(val vertices:List<Pair<Double,Double>>,val rotation:Double)
    fun ease(x:Double,x1:Double,y1:Double,x2:Double,y2:Double):Double {
        if(x<=0) return 0.0
        if(x>=1) return 1.0
        var low=0.0;var high=1.0
        repeat(36) { val t=(low+high)/2;val v=3*(1-t)*(1-t)*t*x1+3*(1-t)*t*t*x2+t*t*t;if(v<x) low=t else high=t }
        val t=(low+high)/2;return 3*(1-t)*(1-t)*t*y1+3*(1-t)*t*t*y2+t*t*t
    }
    fun at(fraction:Double):Frame {
        val p=if(fraction.isFinite()) ((fraction%1)+1)%1 else 0.0
        val segment=(0..6).last { offsets[it]<=p }
        val t=ease((p-offsets[segment])/(offsets[segment+1]-offsets[segment]),.34,1.45,.4,1.0)
        val a=polygons[segment];val b=polygons[segment+1]
        return Frame((0..47).map { i -> (a[i*2]+(b[i*2]-a[i*2])*t)/100 to (a[i*2+1]+(b[i*2+1]-a[i*2+1])*t)/100 },
            rotations[segment]+(rotations[segment+1]-rotations[segment])*t)
    }
    fun reducedOpacity(fraction:Double):Double {
        val p=if(fraction.isFinite()) ((fraction%1)+1)%1 else 0.0
        val t=ease(if(p<.5) p*2 else (p-.5)*2,.42,0.0,.58,1.0)
        return if(p<.5) 1-.6*t else .4+.6*t
    }
